<script setup>
import {ref,computed} from 'vue';import{Plus,Search,Pencil,Trash2}from'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import Modal from '../components/Modal.vue';import{state,persist}from'../data/store'
const q=ref(''),show=ref(false),editId=ref(null),form=ref({name:'',description:''});const filtered=computed(()=>state.categories.filter(c=>(c.name+' '+c.description).toLowerCase().includes(q.value.toLowerCase())))
function open(c=null){editId.value=c?.id??null;form.value=c?{...c}:{name:'',description:''};show.value=true}function save(){if(!form.value.name)return;if(editId.value)Object.assign(state.categories.find(c=>c.id===editId.value),form.value);else state.categories.push({...form.value,id:Date.now(),active:true});persist();show.value=false}function remove(c){if(confirm(`Excluir ${c.name}?`)){state.categories.splice(state.categories.indexOf(c),1);persist()}}
</script><template><PageHeader title="Categorias" subtitle="Organize os produtos por categorias."><button class="btn btn-primary" @click="open()"><Plus :size="18"/>Nova categoria</button></PageHeader><section class="panel"><div class="toolbar"><div class="search"><Search :size="18"/><input v-model="q" placeholder="Buscar categoria..."/></div></div><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Descrição</th><th>Produtos</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id"><td><b>{{c.name}}</b></td><td>{{c.description}}</td><td>{{state.products.filter(p=>p.category===c.name).length}}</td><td><span class="badge badge-success">Ativa</span></td><td class="actions"><button class="icon-btn" @click="open(c)"><Pencil :size="17"/></button><button class="icon-btn danger-text" @click="remove(c)"><Trash2 :size="17"/></button></td></tr></tbody></table></div></section><Modal v-if="show" :title="editId?'Editar categoria':'Cadastrar categoria'" @close="show=false"><form class="form-grid" @submit.prevent="save"><div class="field full"><label>Nome</label><input v-model="form.name" required/></div><div class="field full"><label>Descrição</label><textarea v-model="form.description" rows="4"></textarea></div><div class="modal-actions full"><button type="button" class="btn btn-secondary" @click="show=false">Cancelar</button><button class="btn btn-primary">Salvar categoria</button></div></form></Modal></template>
